import{_ as n,l as s,o as e,c as P,v as t,p as i,x as o,d as l,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"P 与 NP","description":"","frontmatter":{"title":"P 与 NP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/p-vs-np.md","filePath":"cs/p-vs-np.md","lastUpdated":1789023840000}'),h={name:"cs/p-vs-np.md"};function c(A,a,N,E,_,m){const r=s("Mermaid");return e(),P("div",null,[a[1]||(a[1]=t('<h1 id="p-与-np" tabindex="-1">P 与 NP <a class="header-anchor" href="#p-与-np" aria-label="Permalink to &quot;P 与 NP&quot;">​</a></h1><div class="epigraph"><p>P 是多项式时间可解的判定问题；NP 是多项式时间可验证的判定问题。它们是否相等，本课不裁决。</p><footer>—— 据 Cook, The Complexity of Theorem-Proving Procedures, 1971；Garey and Johnson, Computers and Intractability, 1979 整理</footer></div><p>上一课<a href="/cs/interval-dp">区间 DP 直觉</a>给出伪多项式 DP，并留下「\\(W\\) 以二进制写入时表有多大」的缺口。此前排序、图算法、KMP 都默默停在多项式时间内，从未命名这个圈子。本课不从图灵机重讲计算是什么。缺口是：<strong>给判定问题的两类</strong>——P 与 NP——并说明 0-1 背包判定版为什么自然落在 NP，而不在本课证明它完全。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>判定问题：输入 \\(x\\)，回答是/否。P：存在最坏多项式时间算法。本栏已见的排序判定（「是否已有序」）、最短路可行性、连通性，都在 P。NP：存在多项式长证书，多项式时间验证器：是实例有某证书被接受，否实例任何串都不被接受。</p><p>0-1 背包判定「能否达到价值 \\(\\ge K\\)」：证书是选哪些物品，验证加总重量与价值。找证书可以很难；验证书是线性。这就是 NP 的形状。本课不把非确定性图灵机展开成状态表。</p><h3 id="np-不是「非多项式」" tabindex="-1">NP 不是「非多项式」 <a class="header-anchor" href="#np-不是「非多项式」" aria-label="Permalink to &quot;NP 不是「非多项式」&quot;">​</a></h3><p>NP 不读 Non-Polynomial。它包含 P（多项式算法的运行记录可当证书）。未知的是是否 NP \\(\\subseteq\\) P。本课不引用未发表的证明，也不把「实践中指数」写成 NP 定义。</p><p><span class="marginnote">Cook 1971 定义多项式时间归约与 SAT 完全性；Karp 1972 列出一批。Garey/Johnson 是标准清单。本课只建类；归约与完全性是后两课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把优化改写成判定（有没有价值 \\(\\ge K\\) 的子集）。展示短证书与验证器。承认搜索可指数（枚举子集），验证多项式。P 的成员给算法；NP 的成员给验证器。 coNP 点名：否实例的短证，本课不展开。</p>',11)),(e(),i(d,null,{default:o(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEC%5B%22%E5%88%A4%E5%AE%9A%E9%97%AE%E9%A2%98%22%5D%20--%3E%20PCLS%5B%22P%EF%BC%9A%E5%A4%9A%E9%A1%B9%E5%BC%8F%E5%8F%AF%E8%A7%A3%22%5D%0A%20%20DEC%20--%3E%20NPCLS%5B%22NP%EF%BC%9A%E5%A4%9A%E9%A1%B9%E5%BC%8F%E5%8F%AF%E9%AA%8C%E8%AF%81%22%5D%0A%20%20PCLS%20--%3E%20INCL%5B%22P%20%E2%8A%86%20NP%22%5D%0A%20%20NPCLS%20--%3E%20OPEN%5B%22%E6%98%AF%E5%90%A6%E7%9B%B8%E7%AD%89%EF%BC%9A%E5%BC%80%E6%94%BE%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><a href="/cs/asymptotic-notation">渐近记号</a>里的多项式对输入长度，不是对数值 \\(W\\) 本身。背包 DP 的 \\(\\Theta(nW)\\) 因此不一定把判定版放进 P。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了类，才能说「多项式归约保持哪一类」。本课不写归约。也不把图灵机模型与 RAM 模型的多项式差异展开：标准约定下二者多项式等价，后课归约默认这一层。</p><p>优化问题「找出最大价值」不是判定类的对象；它对应的判定在 NP，搜索可能 NP-难，用语留给后课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列 NPC 清单，不证 SAT 完全。不把素数判定的历史（AKS 在 P）写成主线。加密、平均复杂度不进。后课默认：谈到 NP，即短证书可验；P 即多项式算法。归约是下一课的缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>P = 多项式可解判定；NP = 多项式可验证判定；\\(P\\subseteq NP\\)。</li><li>先前算法课的对象默认在 P；背包判定是 NP 的直觉例子。</li><li>NP 不是「指数」的同义词；\\(P=NP\\) 开放。</li><li>出处：Cook, 1971；Garey and Johnson, 1979。</li></ul>',8))])}const f=n(h,[["render",c]]);export{C as __pageData,f as default};
